        WHEN o.type IN ('U','V') THEN N'TABLE'
        WHEN o.type = 'P'        THEN N'PROCEDURE'
        WHEN o.type IN ('FN','IF','TF') THEN N'FUNCTION'
    END
FROM sys.objects o
JOIN sys.schemas s ON s.schema_id = o.schema_id
WHERE s.name = 'dbo' AND o.name = 'Catalog'
  AND o.type IN ('U','V','P','FN','IF','TF');
IF @lvl1 IS NULL
    PRINT N'WARN: dbo.Catalog not found in EDS as table/view/procedure/function — skipping MS_Description';
ELSE IF EXISTS (
    SELECT 1 FROM sys.fn_listextendedproperty(
        N'MS_Description', N'SCHEMA', 'dbo', @lvl1, 'Catalog', NULL, NULL)
)
    EXEC sp_updateextendedproperty
        @name = N'MS_Description',
        @value = N'Vendor-published catalog — a named container that groups a set of `CrossRefs` entries (~4K rows). One vendor may publish multiple catalogs (e.g., per product line or per bid award).',
        @level0type = N'SCHEMA', @level0name = 'dbo',
        @level1type = @lvl1,     @level1name = 'Catalog';
ELSE
    EXEC sp_addextendedproperty
        @name = N'MS_Description',
        @value = N'Vendor-published catalog — a named container that groups a set of `CrossRefs` entries (~4K rows). One vendor may publish multiple catalogs (e.g., per product line or per bid award).',
        @level0type = N'SCHEMA', @level0name = 'dbo',
        @level1type = @lvl1,     @level1name = 'Catalog';
GO

