        WHEN o.type IN ('U','V') THEN N'TABLE'
        WHEN o.type = 'P'        THEN N'PROCEDURE'
        WHEN o.type IN ('FN','IF','TF') THEN N'FUNCTION'
    END
FROM sys.objects o
JOIN sys.schemas s ON s.schema_id = o.schema_id
WHERE s.name = 'dbo' AND o.name = 'Items'
  AND o.type IN ('U','V','P','FN','IF','TF');
IF @lvl1 IS NULL
    PRINT N'WARN: dbo.Items not found in EDS as table/view/procedure/function — skipping MS_Description';
ELSE IF EXISTS (
    SELECT 1 FROM sys.fn_listextendedproperty(
        N'MS_Description', N'SCHEMA', 'dbo', @lvl1, 'Items', NULL, NULL)
)
    EXEC sp_updateextendedproperty
        @name = N'MS_Description',
        @value = N'Master product catalog (~44M rows) — normalized, vendor-agnostic items that vendor offerings link to via `CrossRefs`. Categorized by `Category` and (where applicable) attributed to a `Manufacturers` record.',
        @level0type = N'SCHEMA', @level0name = 'dbo',
        @level1type = @lvl1,     @level1name = 'Items';
ELSE
    EXEC sp_addextendedproperty
        @name = N'MS_Description',
        @value = N'Master product catalog (~44M rows) — normalized, vendor-agnostic items that vendor offerings link to via `CrossRefs`. Categorized by `Category` and (where applicable) attributed to a `Manufacturers` record.',
        @level0type = N'SCHEMA', @level0name = 'dbo',
        @level1type = @lvl1,     @level1name = 'Items';
GO

