DECLARE @lvl1 sysname;
SELECT @lvl1 = CASE
        WHEN o.type IN ('U','V') THEN N'TABLE'
        WHEN o.type = 'P'        THEN N'PROCEDURE'
        WHEN o.type IN ('FN','IF','TF') THEN N'FUNCTION'
    END
FROM sys.objects o
JOIN sys.schemas s ON s.schema_id = o.schema_id
WHERE s.name = 'dbo' AND o.name = 'ResetPasswordTracking'
  AND o.type IN ('U','V','P','FN','IF','TF');
IF @lvl1 IS NULL
    PRINT N'WARN: dbo.ResetPasswordTracking not found in EDS as table/view/procedure/function — skipping MS_Description';
ELSE IF EXISTS (
    SELECT 1 FROM sys.fn_listextendedproperty(
        N'MS_Description', N'SCHEMA', 'dbo', @lvl1, 'ResetPasswordTracking', NULL, NULL)
)
    EXEC sp_updateextendedproperty
        @name = N'MS_Description',
        @value = N'Password-reset email audit (~125K rows). One row per reset request with the issued `ResetPasswordCode`, target email, district / school context, and action / error payload. Indexed on `ResetPasswordCode` for verification.',
        @level0type = N'SCHEMA', @level0name = 'dbo',
        @level1type = @lvl1,     @level1name = 'ResetPasswordTracking';
ELSE
    EXEC sp_addextendedproperty
        @name = N'MS_Description',
        @value = N'Password-reset email audit (~125K rows). One row per reset request with the issued `ResetPasswordCode`, target email, district / school context, and action / error payload. Indexed on `ResetPasswordCode` for verification.',
        @level0type = N'SCHEMA', @level0name = 'dbo',
        @level1type = @lvl1,     @level1name = 'ResetPasswordTracking';
GO

